import numpy as np

class QLearning:
    def __init__(self, alpha, gamma, epsilon, epsilon_decay=0.995, min_epsilon=0.01):
        self.alpha = alpha
        self.gamma = gamma
        self.epsilon = epsilon
        self.epsilon_decay = epsilon_decay
        self.min_epsilon = min_epsilon
        self.q_table = {}

    def get_action(self, state, action_space):
        if np.random.rand() < self.epsilon:
